from datetime import datetime
if value is None or len(value) == 0:
	return 'No data recorded'
row = value[0]
if row['entryDate'] is None:
	return 'No data recorded'
try:
	d = row['entryDate']
	if hasattr(d, 'strftime'):
		return 'Last entry: ' + d.strftime('%m/%d/%Y')
	return 'Last entry: ' + str(d)[:10]
except:
	return 'No data recorded'

if value is None or len(value) == 0:
	return None
maxDev = 0.0
for row in value:
	dev = row.get('deviation', 0) or 0
	if abs(dev) > maxDev:
		maxDev = abs(dev)
return maxDev if maxDev > 0 else None

result = {}
if value is None:
	return result
for row in value:
	eqId = str(row.get('equipmentId', ''))
	paramId = str(row.get('parameterId', ''))
	val = row.get('value', None)
	if eqId not in result:
		result[eqId] = {}
	result[eqId][paramId] = val
return result

result = {}
if value is None:
	return result
for row in value:
	month = str(row.get('month', ''))
	result[month] = row.get('baselineDAT', None)
return result

transforms.code:
if value is None: return system.dataset.toDataSet([], [])
try:
	selected = self.view.custom.selectedEquipment
except:
	selected = 'all'
pen_names = ['IWT Actual','POGT Actual','DAT Actual','IWT Target','POGT Target','DAT Target']
time_data = {}
count_data = {}
for r in range(value.getRowCount()):
	ts    = value.getValueAt(r, 't_stamp')
	eq_id = str(value.getValueAt(r, 'coolingTowerDataID') or '')
	pl    = str(value.getValueAt(r, 'paramLabel') or '')
	v     = value.getValueAt(r, 'value')
	if selected != 'all' and eq_id != str(selected): continue
	if pl not in pen_names: continue
	if ts not in time_data:
		time_data[ts] = {}
		count_data[ts] = {}
	if v is not None:
		if pl in time_data[ts] and time_data[ts][pl] is not None:
			time_data[ts][pl] = (time_data[ts][pl] * count_data[ts].get(pl,1) + v) / (count_data[ts].get(pl,1) + 1)
			count_data[ts][pl] = count_data[ts].get(pl,1) + 1
		else:
			time_data[ts][pl] = v
			count_data[ts][pl] = 1
headers = ['t_stamp'] + pen_names
rows = [[ts] + [time_data[ts].get(p) for p in pen_names] for ts in sorted(time_data.keys())]
return system.dataset.toDataSet(headers, rows)

config.script:
iwtVal = self.getSibling('IWTGlobal').props.value
if iwtVal is None:
	return
for eqType in ['MAC', 'BAC', 'RNC', 'FNC', 'GOX', 'GAN', 'CDA', 'MISC']:
	instances = getattr(self.view.custom, eqType).Instances
	updated = []
	for inst in instances:
		newInst = dict(inst)
		newInst['designIncomingWaterTempF'] = iwtVal
		if newInst.get('processGasOutTempF') is not None:
			newInst['designApproachTempF'] = newInst['processGasOutTempF'] - iwtVal
		updated.append(newInst)
	getattr(self.view.custom, eqType).Instances = updated

import system
siteId = self.view.params.siteId
if not siteId:
	system.perspective.openPopup('saveErr', 'Framework/ErrorPopup', params={'message': 'No site selected. Cannot save.'})
	return

# collect entry date from toolbar
try:
	entryDate = self.getSibling('EntryDatePicker').props.value
except:
	entryDate = system.date.now()

if entryDate is None:
	system.perspective.openPopup('saveErr', 'Framework/ErrorPopup', params={'message': 'Please select an entry date.'})
	return

rows = []

# Gather instances from each equipment type
for eqType in ['MAC', 'BAC', 'RNC', 'FNC', 'GOX', 'GAN', 'CDA', 'MISC']:
	try:
		instances = getattr(self.view.custom, eqType).Instances
	except:
		instances = []
	for inst in instances:
		iwt = inst.get('designIncomingWaterTempF', None)
		pogt = inst.get('processGasOutTempF', None)
		if iwt is None and pogt is None:
			continue
		rows.append({
			'equipmentId': inst.get('id', 0),
			'siteId': siteId,
			'entryDate': entryDate,
			'designIncomingWaterTempF': iwt,
			'processGasOutTempF': pogt,
			'designApproachTempF': inst.get('designApproachTempF', None),
			'approachTempTarget': inst.get('approachTempTarget', None),
			'incomingWaterTempTarget': inst.get('incomingWaterTempTarget', None),
			'processGasOutTempTarget': inst.get('processGasOutTempTarget', None)
		})

if len(rows) == 0:
	system.perspective.openPopup('saveErr', 'Framework/ErrorPopup', params={'message': 'No temperature values entered. Please enter at least one IWT or POGT value.'})
	return

try:
	for row in rows:
		system.db.runNamedQuery(
			project='Cooling_Tower_Approach_Temps',
			path='coolingTowerData/insertCoolingTowerData',
			parameters={
				'equipmentId': row['equipmentId'],
				'siteId': row['siteId'],
				'entryDate': row['entryDate'],
				'designIncomingWaterTempF': row['designIncomingWaterTempF'],
				'processGasOutTempF': row['processGasOutTempF'],
				'designApproachTempF': row['designApproachTempF'],
				'approachTempTarget': row['approachTempTarget'],
				'incomingWaterTempTarget': row['incomingWaterTempTarget'],
				'processGasOutTempTarget': row['processGasOutTempTarget']
			}
		)
	noteText = self.view.custom.notesText
	if noteText and noteText.strip():
		system.db.runNamedQuery(
			project='Cooling_Tower_Approach_Temps',
			path='coolingTowerData/insertNote',
			parameters={
				'siteId': siteId,
				'noteDate': entryDate,
				'noteText': noteText.strip()
			}
		)
		self.view.custom.notesText = ''
	system.perspective.openPopup('saveOK', 'Framework/SuccessPopup', params={'message': 'Data saved successfully for ' + str(len(rows)) + ' equipment rows.'})
except Exception as e:
	system.perspective.openPopup('saveErr', 'Framework/ErrorPopup', params={'message': 'Save failed: ' + str(e)})

siteId = self.view.params.siteId
if not siteId:
	return
monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
monthRows = ['JanRow','FebRow','MarRow','AprRow','MayRow','JunRow','JulRow','AugRow','SepRow','OctRow','NovRow','DecRow']
for i, rowName in enumerate(monthRows):
	monthNum = i + 1
	try:
		val = self.getSibling(rowName).getChild('Input').props.value
	except:
		val = None
	if val is not None:
		system.db.runNamedQuery(
			project='Cooling_Tower_Approach_Temps',
			path='coolingTowerData/upsertSeasonalBaseline',
			parameters={'siteId': siteId, 'month': monthNum, 'baselineDAT': val}
		)
system.perspective.openPopup('baselineOK', 'Framework/SuccessPopup', params={'message': 'Seasonal baselines saved.'})
